INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи нақши оғорини қушқарорӣ дар саломатии гири чинӣ</h2>\n<p>Чинӣ яке аз муҳимтарин маҳсулоти маишӣ ва озод мебошад, ки ҳассосияти баланд ба шароити намии хок дорад. Яке аз мушкилоти асосии деҳқонон дар паҳлӯи парвариши чинӣ, мубориза бо зараррасонҳо ва бемориҳои қорӣ мебошад, ки аксар вақт сарчашмаи об ва намии иловагӣ доранд. Дар ин бахш мо мехоҳем нишон диҳем, ки чӣ тавр истифода аз системаҳои <a href="https://navar-abyari.ir/al-ray-al-satahi/">рӯшноии сатҳӣ</a> дар канори технологияи оғорини қушқарорӣ, метавонад муҳити рушди чиниро беҳтар кунад. Ба ҷои оғорини оварӣ, ки боиси таршавии пӯстроки афлакмону (сибҳо) ва пайдо намудани намӣ дар ҳавои атрофи гири мекунад, оғорини қушқарорӣ бевосита решаҳоро ҳадаф мегиряд ва аз паҳкунии об бар болои сибҳо (булбҳо) пешгирӣ мекунад. Ин усул на танҳо талафоти аз бемориҳои қориро кам мекунад, балки бо танзими дақиқи миқдори об, аз рушди зиёди отлаҳҳо ва зараррасони хокӣ, ки вобаста ба муҳити тар мебошанд, низ кам мекунад. Барои дарки беҳтари зичии намуд, ки ба зичии зараррасонҳо таъсир мерасонад, метавонед ба <a href="https://navar-abyari.ir/garlic-seed-per-hectare-factors-increase-37460-2/">миқдори бӯди чинӣ дар гектар</a> ишора кунед.</p>\n\n\n\n<h2>Таъсири намии танзимшуда ба бемориҳои қории чинӣ</h2>\n<p>Бемориҳои қорӣ, аз ҷумла зинги чинӣ, таробидани сафед ва дағонҳои қаҳваранг, дар шароитҳо, ки намии нисбӣ баланд ва тар будани баргҳо вуҷуд дорад, паҳн мешаванд. Системаҳои оғорини қушқарорӣ бо камунии намии сатҳии баргҳо, занҷираи рушди қориро мебарранд. Аммо ин танҳо як қисми ҳодиса аст; идоракунии кимиёӣ ва биологӣ низ лозим аст. Агар аз системаҳои қадимии оғорини пашшакунӣ истифода баред, эҳтимоли сироят тавассути қатраҳои об чанд баробар зиёд мешавад. Дар муқобили ин, <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D8%B3%DB%8C%D8%B3%D8%AA%D9%85-%D9%87%D8%A7%DB%8C-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C/">Навъҳои системаҳои оварӣ</a> Истифодаи системаҳои муосиру фертigation имкон медиҳад, ки моддаҳои қаззубардор ё моддаҳои ғизоии зарур барои ниҳолро бевосита ба соҳаи решаҳо расонем. Ин кор системаи муҳофизатии ниҳолро қавӣ мекунад. Вақте ки ниҳол қавӣ бошад, муқовиматаш ба ҳуҷуми псевалиду моҳикҳои обӣ, ки инкишофдиҳандаи баъзе бемориҳо мебошанд, афзуда мешавад. Инчунин, бо кам шудани зарурати об, хароҷоти муқобили ҳашарот намояндаш мекунад ва маҳсули ниҳоӣ дар бозор ҷозибатари мегирад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سیر-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های سیر با آبیاری قطره‌ای - تصویر 1"/><figcaption>ҳашарот ва бемориҳои ҳашарот оварии қатрагӣ сирпиёз</figcaption></figure>\n\n<h3>Нақши системаи чӯмаи оварӣ дар назорати шашкал ва пӯсидашавии реша</h3>\n<p>Шашкали сирпиёз яке аз ҳашароти маъруфи ин маҳсул мебошад, ки бо намии баланди хок ва кӯкарти зич бештар паҳн мешавад. Истифодаи хатҳои чӯмаи оварӣ, ки бевосита зери решаи ниҳол ҷойгир мешаванд, боиси мешавад, ки намӣ танҳо дар соҳаи реша нигоҳ дошта шавад ва сатҳи хок хушк боқӣ монад. Ин хушкӣи нисбии сатҳӣ монеи рушди борик ва парҳамҳои он мегардад. Бисёр ҳашаротбоносон бо истифода аз <a href="https://navar-abyari.ir/%d9%85%d8%b2%d8%a7%db%8c%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%a8%d8%ba%d9%84-%d8%af%d9%88%d8%ae%d8%aa/">Бенозириҳои чӯмаи оварии дар канори ҷойи кӯк</a> фаҳмидаанд, ки бо интиқоли намӣ аз роҳи ҳаракати ҳашарот, миқдори зарари кураша ва шашкал ба дараҷаи назаррас коҳиш меёбад. Илова бар ин, назорати дақиқи об монеи бемории пӯсидашавии нарми реша мешавад, ки дар хокҳои вазнин ва обнок маъмул аст.</p>\n\n\n\n<h2>Баҳодиҳии ҳашаротҳои бактериявӣ ва вирусӣ бо ёрии оварии ҳوشмон</h2>\n<p>ҳашароти бактерӣ, ба монанди пӯсиши сир ва вирусҳои мозаикӣ низ ба камбудии ҳаёти гиёҳ барои мубориза ғайриқобилият доранд. Вақте ки гиёҳи сир дар шиддати обӣ бошад (ё камбудӣ ё зиёд), системаи муҳофизати он заиф мешавад. Обёрӣи тамчилӣ бо нигоҳ доштани таркиби доими рӯйи рӯӣ, шиддати гиёҳро кам мекунад. Ин устуворӣ имкон медиҳад, ки гиёҳ қудрати худро барои истеҳсоли маҳсул масарф кунад, на барои барқарор кардани ҳуҷайраҳои аз пӯсидан осебдида. Агар аломатҳои бемории бактерӣ ба назар расад, истифодаи системаҳои филтратсияи дақиқ дар обёрӣи тамчилӣ муҳим аст, то даромадани фаҳири бемории дар об маҳлалшуда ба рӯйро пешгирӣ кунад. Инчунин, метавон иловаи моддаҳои муқобили бактериявиро тавассути паҳн кардани маҳлул бо обёрӣи тамчилӣ истифода бурд. Барои шиносоӣ бо zichaи гузоштани мувофиқ, ки худ омиле барои пешгирӣ шудани зиёдатии ҳашарот аст, ҷадвал <a href="https://navar-abyari.ir/triticale-seed-per-hectare-density-table/">зичии гузоштани тритикале</a> ро метавон ҳамчун намуна барои муқоисаи фосилагузорӣ дар кӯшишҳои баргирандарӣ баҳодиҳӣ кард, гарчанде ки принсипҳои монатарбар барои баргирандарӣ ҳам татбиқ мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سیر-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های سیر با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation сир</figcaption></figure>\n\n<h3>таъсири ҳашароти пашавона ва мӯрдаи сафед</h3>\n<p>мӯрдаи сафед ва пашавонаи хокӣ аксар вақт барои ҳосилниҳолӣ ба таркиби хок ниёз доранд. Дар системаҳои обёрӣи тамчилӣ, таркиб дар ҳарараи рӯй марказӣ аст ва аз сатҳи хок берананда аст. Ин тақсимоти якҳамвории таркиб имкон медиҳад, ки ҳашарот наметавонанд минтақаҳои хушкро байни сатҳҳо барои зинда мондан интихоб кунанд. Дар натиҷа, зичии аҳолии ҳашарот кам мешавад. Инчунин, шаффофияти баланд дар системаҳои зер фишор имконро фароҳам меорад, ки моддаҳои кимиёвии муқобили ҳашарот илова шаванд, то ки гиёҳ аз дохил муҳофизат шуда бошад. Ин усул камтар боиси эҷоди ҳашароти муқовиматманд мегардад, нисбат ба паҳн кардани такрорӣ дар сатҳ. Барои кишовароне, ки дар ҷустуҷӯи кӯшишҳои пайдарпай ҳастанд, шиносоӣ бо <a href="https://navar-abyari.ir/carrot-seed-quantity-per-hectare-guide/">миқдори бодак чакӯб дар гектар</a> Идоракунии хашар ҳам метавонад дар нақшаи чархи зерокорӣ ва шикастани даврии хашарҳои сиръ муассир бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سیر-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های سیر با آبیاری قطره‌ای - تصویر 3"/><figcaption>хашарҳо ва бемориҳои ҳосил, обёрӣ-андозӣ, сиръ</figcaption></figure>\n\n\n\n<h2>Қоидаҳои амалӣ барои кам кардани бемориҳои иктимолӣ бо системаи обёрӣ-андозӣ</h2>\n<ul>\n  <li><strong>Мурӯб баробар будани фаввоси обёрӣ:</strong> Барои сиръ, обёрӣҳои кӯтоҳ ва пайдарпай бештар аз обёрӣҳои дароз ва ғайридаимӣ муфид аст. Ин амал маҷбур кардани пурраи решаҳо ва намӣ-бахшӣ аз ҳад зиёди боми сиръро пешгирӣ мекунад.</li>\n  <li><strong>Моҳири филтрҳо:</strong> Филтрҳои тормоқ ё дискрӯй бояд ҳар ҳафта санҷида шаванд, то ба ифлосӣ-пайдории сӯрохиҳо барои обёрӣ-андозӣ ва кам шудани фишори баробар ҷоҳоро надиҳад. Фишори номишқул сабаби рушди ғайрибаробари гиёҳ ва зиёд будани осебпазирӣ ба хашарҳо мешавад.</li>\n  <li><strong>Истифодаи пластикаи таврунда:</strong> Дар ҷанби нӯҳури тип, истифодаи пластики торик ҳамчун малчӣ дараҷаи намӣ-и сатҳиро кам мекунад ва аз партобидани хок заҳрнок ба баргҳо пешгирӣ мекунад. Ин техника дар ҷанби <a href="https://navar-abyari.ir/raining-pipes-types-and-uses/">Нақши ҷӯраҳои баронӣ дар обёрӣ</a> дар дигар маҳсулот ҳам монанд аст, вале дар сармо диққат ба хушкӣ-и сатҳӣ ҷамъ мешавад.</li>\n  <li><strong>Тозагӣ-и асбобҳо:</strong> Пеш аз оғози мавсим, системаи обёрӣ бояд бо маҳлулҳои тазекунанда шуста шавад, то бактерияҳои боқимонда аз соли минвалӣ дар ҷӯраҳо боқӣ намонанд.</li>\n</ul>\n\n<h2>Саволҳои оддӣ (FAQ)</h2>\n<ol>\n  <li><strong>Оё обёрӣ-и қатрагӣ метавонад ҷойгузини пурраи семпунокӣ бошад?</strong><br>Не, обёрӣ-и қатрагӣ як воситаи пешгирӣ аст. Бо кам шудани заминаи мусоид барои афзоиши зараррад ва беморӣ, ниёз ба семпунокӣ кам мешавад, вале агар зарарради фаъол дидан шавад, ҳаракатҳои назорати кимиёвӣ ҳанӯз ҳам лозим аст.</li>\n  <li><strong>Беҳтарин вақти барқарор кардани обдиҳӣ барои пешгирӣ аз пӯсиши саримпоъ пас аз ҷамъоварӣ кадом аст?</strong><br>Тақрибан 14 рӯз пеш аз ҷамъоварӣ, обдиҳӣ бояд боздошта шавад, то саримпоъҳо фурсат дошта бошанд, ки хушк шаванд ва пӯст хӯрда шаванд. таркиши зиёд дар ин марҳила ба пӯсиш дар анбор оварда мерасонад.</li>\n  <li><strong>Оё системаи обдиҳии банддор барои саримпоъ бо равонишӣ мувофиқ аст?</strong><br>Саримпоъ ба равонишӣ ҳассос аст. Истифодаи банддор чун дарозии кам ва пайдарпай будан, равонишӣ-ро ба ҳадди ақалл меорад. Агар равонишӣ вуҷуд дошта бошад, бояд масоҳати байни хатҳо зиёд карда шавад ё филтърҳои махсуси равонишӣ илова карда шаванд.</li>\n</ol>\n\n<h2>Хулоса ва дидбанд ояндаи пеш</h2>\n<p>Идоракунии зараранодон ва бемориҳои саримпоъ бо обдиҳии заррон (капель) танҳо як усули техникӣ нест, балки тағйири дидбаён барои кишоварзҳои дақиқ мебошад. Бо тавассути омехта кардани обдиҳии заррон ё банддор, парҳезгирии абшаванда ва назорати мунтазам, ҳам ҳароси бемориҳои қурракӣ ва бактериявиро кам кардан мумкин аст ва ҳам истифодаи об ва энергияро беҳтар карда мешавад. Кишоварзӣи Эрон бо вуҷуди гуногунии иқлим, тавассути ин техникаҳо, сифати саримпои худро ба сатҳи ҷаҳонӣ мерасонад. Фикр кунед, ки пешгирӣ ҳамеша арзонтар аз табобат аст. Бо истифода аз донишҳои муносиб монанди миқдори бодаи чечеб дар гектар ва принсипҳои тартиби зеробӣ, давраи ҳаёти зараранодонҳоро ба таври самараноктар идора кардан мумкин аст. Ояндаи котиби саримпоъ дар Эрон, вобаста ба амалӣ кардани чунин системаҳои ғангӣ ва марказёфта шуда аз рӯи гиёҳ аст.</p>','Азои ва беморҳои сабзбиббо бо обёрӣ-андозии қатқатӣ: Чораҳои амалӣ барои зиёд намудани ҳосил ва кам кардани зарар','Дар ин мақола мо баррасӣ мекунем, ки чӣ тавр системаҳои обёрӣи қатрагӣ ва наварии таҳпӣ метавонанд ба назорати зарароварон ва бемориҳои шаҳрӣ ва бактериявии саримон кӯмак расонанд. Принсипҳои танзими об, кам кардани намии хок ва идоракунии дақиқи раҳиҳро ошно шавед.','publish','closed','closed','afat-ham-bemori-ho-yi-sir-bo-obori-qat-qati',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
