INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Тақризи муҳими ороиши қатрагӣ дар кунҳи соя</h2>\n<p>Соя яке аз равғанҳои бой ва ғалладони арзиши иқтисодӣ аст, ки барои рушди беҳтарин ба идоракунии дақиқи намии хок ниёз дорад. Дар шартҳои хушк ва нимхушк, <strong>кунҳи соя бо ороиши қатрагӣ</strong> ё нӯри ти (Drip Tape) роҳи самаранок барои коҳиши талафоти об ва зиёд шудани самаранокӣ аст. Ин усул роҳи бевосита барои расонидани об ва моддаҳои ғизоӣ ба решаҳои баргиста аст ва сабаб мегардад, ки баргиста тавонад энергияи худро барои истеҳсоли биомасса ва дон истроя диҳад, на танҳо ҷустуҷӯи об.</p>\n<p>Дар ин мақола мо роҳнамои қатъ-ба-қатъро пешниҳод мекунем, ки чӣ тавр аз кунҳ то ҷамъоварӣ, як системаи ороиши қатрагии самаранокро барои соя тарҳрезӣ ва амалӣ кунед. Аз интихоби лӯлаи мувофиқ то тақсимоти ороиш, мо ҳама чизро баррасӣ мекунем, то тавонед меҳвари якхела ва солим дошта бошед.</p>\n\n\n\n<h2>Муносибатҳои асосии истифодаи нӯри ти дар кунҳи соя</h2>\n<p>Системаҳои ороиши қатрагӣ, ба таври ахсо нӯри ти, хусусиятҳои алоҳидаро доранд, ки барои соя бисёр муносибат дорад. Дар поён муҳимтарин муносибатҳоро баррасӣ мекунем:</p>\n<ul>\n<li><strong>Ҷабҳанокӣ дар об:</strong> Система таматан-таматан обро шуданро танҳо ба минтакаи реша (Root Zone) маҳдуд мекунад ва буғурӯии рӯро ба ҳадди ақалл мерасонад.</li>\n<li><strong>Кам шудани гиёҳҳои зарарнок:</strong> Азбаски танҳо хатҳои об шӯр мешаванд, қисмҳои хушки байни хатҳо муҳити мувофиқ барои афзоиши гиёҳҳои зарарнокро фароҳам намемекунанд.</li>\n<li><strong>Боло рафтан тағлиқи оҳангорӣ:</strong> Имконияти тоқир кардани оҳангҳои дар об ҳалшаванда (Fertigation) ба таври мустақим ба реша, ки фурӯ бурдани беҳтари моддаҳои ғизоӣ, ба монанди нитроген ва фосфарро фароҳам меорад.</li>\n<li><strong>Кам шудани хароҷоти коркарди одамӣ:</strong> Баъд аз насб кардани ибтидоӣ, ниёз ба дахолишҳои зиёдаи одомӣ барои об шӯр сарира кам мешавад.</li>\n</ul>\n\n<h2>Принсипҳои техникӣ дар нигарондани кард ва фосилагузорӣ чӯпонҳо</h2>\n<h3>Дароии ҷойгиршавии лӯлаҳо</h3>\n<p>Барои соя, аз сабаби решаҳои сатҳии нисбат ба баъзе маҳсулоти нӯрҳои дигар, лӯлаҳоро хеле чуқор накунед. Дерӯи тавсияшуда 10 то 15 сантиметр аст. Дерӯи зиёд боиси мешавад, ки решаҳои ҷавон ба об даст нарасонанд. Агар аз <a href="https://navar-abyari.ir/negahdorii-navori-tip-harajat/">Нигоҳдории навои тиб дар шароити гарм</a> Дар минтақаҳои хушк истифода мебард, ҳатман аз соябон ё пӯшиши мувофиқ дар фасли тобистон истифода кунед, то лӯлаҳо аз хушкории шадид ва таъсири мустақими офтоб дар амон бошанд.</p>\n\n<h3>Фосилаи навоҳои обёрӣ аз сатҳҳои кишоварӣ</h3>\n<p>Муҳимтарин нуқтаи фаннӣ, муайян кардани фосилаи лӯла аз наботот мебошад. Фосилаи стандартии барои соя одатан байни 10 то 15 сантиметр аст. Фосилаи камтар аз 10 сантиметр боиси лъишкшавии зиёдатарини реша ва зиёдшавии хатари бемориҳои коратсиявии решагӣ мегардад. Фосилаи зиёдтар аз 15 сантиметр боиси мешавад, ки решаҳои асосӣ дастрасии нокафии ба манбаъҳои намнокӣ дошта бошанд. Ҳамеша пеш аз кишт, сатҳҳои обёриро нишон диҳед ва пас хаккаш дар роҳҳои хушк (байни навоҳо) кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سویا-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت سویا با آبیاری قطره‌ای - تصویر 1"/><figcaption>usuli kish va obnordagi qatqora va jaduali obnordagi soyu</figcaption></figure>\n\n<h3>Таҳияи шабака ва фишори система</h3>\n<p>Гиром баробори баландии корӣ муҳим аст. Барои намунаҳои стандартии ғарқобор, баландии идеалӣ одатан байни 1 то 2 бар аст. Баландии зиёд ба дурӯзиш ва вобарории лӯлаҳо сабаб мешавад ва баландии кам барои тақсимоти баробари об дар дарозии ғарқобор кифоя нест. Барои санҷиши дурустии насб, ба мақолаи ҳосилнокии солим бар ҳектар муроҷиат кунед, то шавонакҳоро дар назар гиред.</p>\n\n\n\n<h2>Барномаи обёрӣи соя (Jadвали obërii)</h2>\n<p>Барои барномаи дақиқи обёрӣ, бояд марҳилаҳои расидани сояро донед. Соя дар марҳилаҳои ҳассос ба нороҳати об ҳаст, асосан ҳангоми гул задан ва ташаккули мева.</p>\n\n<h3>Марҳилаи дурӯзиш (Az ziraat to canopy)</h3>\n<ol>\n<li><strong>Зирагун то навиштагиӣ:</strong> Дар ин марҳила, решаҳо ҳанӯз расида нестанд. Обёрҳои мӯъмор бо ҳаҷми кам (ҳар 2 то 3 рӯз дар иқлими хушк) масъуд мешавад, то кӯмак ҳамеша намнок бошад, вале обғарқ набошад. Ин кор ба расидани тезтари решаҳо ба самти ғарқобори обёрӣ кӯмак мекунад.</li>\n<li><strong>Диққат ба ҳарорати хок:</strong> Агар ҳарорати хок паст бошад, обёрро сабуқ кунед. Агар хок хунук бошад, шакл камтар намнок мехӯрад.</li>\n</ol>\n\n<h3>Марҳаи рӯшӣи вегетативӣ (Vegetative Stage)</h3>\n<p>Вақте ки раста ба марҳаи V4 (4 нуқта) расад, талабот ба об ба таври зиёд меафзояд. Сероҳоро ҳар 3 то 5 рӯз як бор анҷом диҳед. Дар ин марҳа, мутобиқии байни намӣ ва ҳавои хок муҳим аст. Агар намӣ хеле баланд бошад, бемориҳои қариши баргҳо ба вуҷуд меоянд.</p>\n\n<h3>Марҳаи гулдорӣ ва ташкили кулабки ҳосил (Reproductive Stage)</h3>\n<p>Ин ҳассастарин марҳа барои ҳосил аст. Таҳсилот дар ин давра бевосита ба вазни дониҳо таъсир мерасонад. Сероҳори мунтазам ва якхел сарфи назар нест. Аз тағйироти шадиди намӣ боз истодагӣ кунед.</p>\n\n<h3>Марҳаи пухтарсӣ ва пухтор (Maturity)</h3>\n<p>Вақте ки раста аз намӣ ҷудо шавад ва шохаҳои кулакҳо оғоз ба хушк шудан кунанд, сероҳоро тадриҷан кам кунед. Дар бисёр усулҳои парвариши соя, охирини сероҳори пеш аз ҷамъоварӣ тақрибан 10 то 14 рӯз таввақе мекунад, то дониҳо хушк шаванд ва сифати равғун нигоҳ дошта шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سویا-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت سویا با آبیاری قطره‌ای - تصویر 2"/><figcaption>uslulhoi pakhsh, maojhoi serohori, muloimi soya</figcaption></figure>\n\n<h2>Нуқтаҳои амалӣ барои баланд бардоштани самаранӯӣ</h2>\n<p>Барои иҷрои дурусти кор наъмуниш ва обёрӣ, илова бар принсипҳои умумӣ, ба тафосилоти хурд диққат кардан зарур аст. яке аз калидҳои муҳим сифати боб (бур) ва зичии наъмуниш мебошад. Гарчанде ки дар ин ҷо мо ба соя (сои) диққат дорем, аммо принсипи умумии миқдори боб дар як гектар барои намудҳои гуногуни дон муҳим аст. Сои одатан бо зичии баланд аз 100 набуриш дар метри мураба ҷойгир карда мешавад (вобаста ба навъ). Зичии зиёд боиси рақобати қавӣ байт набуришҳо ва заиф шудани системаи реша мегардад; дар ин ҳолат, обёрӣ даракаторӣ бояд дақиқтар танзим карда шавад, то ба ҳамаи набуришҳо расад.</p>\n\n<p>Инчунин, идоракунии шимикии хеле ҳассос аст. Дар ҳолати наъмуниш, ҳатман ба зехирҳои заҳрнок ва кудҳои асосӣ диққат диҳед. Барои фаҳмидани беҳтари нобудшавии кудҳо дар системҳои даракаторӣ, хондани роҳнамои <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A7%D8%B3%D9%81%D9%86%D8%A7%D8%AC-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">миқдори боб Исфаҳон дар гектар</a> (ки намунаи истифодаи куд ва боб дар метадҳои маҳаллӣ мебошад) метавонад илҳомбахш бошад, ки чӣ тавр густории моддаҳо бо иқлими минтақа мувофиқат мекунад. Барои сои, истифодаи кудҳои микробӣ (Ризобиум) ҳангоми наъмуниш тавсия дода мешавад. Ин бактерияҳо дар хок мемонанд ва аз решаҳо ҷаббида мешаванд, бинобар ин системаи обёрӣ набояд шустушӯи хеле шадид дошта бошад.</p>\n\n<h2>Ҳалли мушкилоти маъмул дар системҳои даракатории сои</h2>\n<p>Яке аз мушкилоти васеънравандаро, ҷамъшавии моддаҳои солибнок дар наздикии навъи дрипҳо аст. Ин вақте рух медиҳад, ки pH об барои ҷамъшавии калсий ва калсий мувофиқ бошад. Барои пешгирии ин мушкилӣ, аз ҳалкории дурусти об пеш аз воридшавии он ба навъҳо истифода кунед ё аз филтрасияни дақиқ боварӣ пайдоед. Илова ба ин, агар дар минтақаи шумо набуришҳои дигар монанди гӯрам ва гандум намуниш дода шаванд, принсипҳои мон барои системҳо бекор мебошанд; масалан, дар бораи гандум, таҳқиқи <a href="https://navar-abyari.ir/wheat-drip-tape-spacing-irrigation-methods/">масофаи наздикии навъи дрип гандум</a> намоиш медиҳад, ки нақши масофагӣ низ барои сои (бо масофаи зиёдатер барои рушди паҳлӯӣ) коркардашаванда аст.</p>\n\n<p>Сабаби дигаре, ки боиси нобудшавии нам (тип) мешавад, партофтани донаҳо аз сӯрохҳои хурд ҳангоми ғарсдонӣ аст. Ҳамеша ҳатман аз муҳофизҳои нам истифода баред ё пеш аз ғарсдонии боб лӯлаҳоро насб кунед, то донаҳои мулғи бевосита ба дохили нам нашаванд ва боздории муштакро эҷод накунанд.</p>\n\n\n\n<h2>Саволҳои оддӣ (FAQ)</h2>\n<h3>Оё метавонам барои ғарсдонии ҳамзамони мулғи ва гулестона аз системаи қатқатӣ истифода барам?</h3>\n<p>Бале, имконпазир аст, агар фосила байни сатҳҳои гулестона ва мулғи идора карда шавад. Системаҳои қатқатӣ имкон медиханд, ки обро аз як шир (вориди) асосӣ ба ду метадал гуногун бо фишорҳои гуногун равона кунед. Аммо ҳатман барои ҳар шоха аз филтрҳои мувофиқ истифода баред.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سویا-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت سویا با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule سویا</figcaption></figure>\n\n<h3>Агар нам дар миён қат шуд, чӣ бояд кард?</h3>\n<p>Ҳамеша ду нам иловагиро дар майдони деҳқони нигоҳ доред. Дар ҳолати даридан, намро бурида, пайвасткунандаи муваққатӣ (copl)-ро бо часпи барқӣ мустаҳкам пӯшед. Дар фасли оянда нам-и нав харед. Таъмири пурраи нам одатан истеъмолкунандаи маблағ буда, барои истеҳсоли самаранок нест, магар он ки системаҳои қатқатии собит (Drip Line) бошад.</p>\n\n<h3>Оё оби камсифат таъсири манфиро бар маҳсулоти мулғи бо усули қатқатӣ мерасонад?</h3>\n<p>Бале. Об бо EC баланд (шӯр) метавонад боқари баргҳоро сӯзад, зеро моеъ дар дохили лӯлаҳо дар зери фишор аз чунубҳо берун меояд ва намак дар қириҳо бӯм мешавад. Барои ин ҳолат, истифодаи муҳассини хок ва шустаниши мунтазам (Leaching) зарур аст.</p>\n\n<h2>Хулоса</h2>\n<p>Корзи соя бо обёрӣ бо қатраҳо роҳи асосӣ барои деҳқонони муосир аст. Бо диққат ба масофаи лӯлаҳо, танзими дурусти фишор ва иҷрои барномаи обёрӣ мувофиқи марҳилаҳои рушд, шумо ҳамроҳ таъмин кардани об ва зиёд кардани ҳосили дунб мехӯред. Фаромӯш накунед, ки ҳеҷ системае бе танзимоти давравӣ комил нест. Баъзе рӯзҳо, хуруҷи нӯлҳоро санҷед ва қобилияти хокро тест кунед. Кишоварии муваффақ натиҷаи комбинатсияи дониш, дақиқӣ ва истифодаи технологияи муносиб аст. Мо умед дорем, ки ин роҳнамо ба шумо имкон медиҳад, ки мавсими ояндаи корзиро бо боварии бештар нақша гиред.</p>\n<p><strong>Мундариҷаҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D8%A7%D8%B1%DA%86%D9%88%D8%A8%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D985D8A7D8B1DA86D988D8A8D987 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Рушнамои муфассали ғаллакниҳодии соя бо обориши нуқтагӣ: принсипҳо, барнома ва нуктаҳои амалӣ','Шиносоӣ бо принсипҳои партофтани соя дар системаҳои обёрӣ пастнафас ва навак Тиб, нуқтаҳои муҳим дар бахши фосила, тартиби обёрӣ ва идоракунии намии хок барои беҳтарин самаранокии мева. Ин мақола дастури амалӣ барои деҳқонон аст.','publish','closed','closed','guid-to-soybean-planting-with-drip-irrigation',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
