INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Мӯқаддима дар бораи муҳимияти муайян кардани миқдори тоҳи мунботи конжад</h2><p>Дқиқати элмӣ дар кишоварзӣ яке аз муҳимтарин омилҳои муваффақияти парвариши конжад мебошад. Бисёре аз деҳқонҳо гарчанде ки нависҳо ва заҳрофзаги мувофиқро доранд, аз сабаби ҳисобнокории нодурусти <strong>миқдори тоҳи конжад дар як гектар</strong> бо мушкилоти мисли зичии зиёди рӯёнаҳо ё мавқеи номувофиқи фосилаҳо бархӯрд мекунанд. Ин масъала ба таври мустақим ба шиддати рақобат барои захираҳои ғизоӣ ва обӣ ва дар натиҷа ба ҳосили охир таъсир мерасонад. Дар ин қисмати мақола, мо кӯшиш мекунем, ки бо такя ба принсипҳои кишоварзӣи муосиру маълумоти таҷрибавӣ, харитои истилоҳӣро барои муайян кардани беҳтарин миқдори тоҳи истифодашаванда тасвир кунем. Диққат диҳед, ки ин ҳисобнокориҳо танҳо рақамҳои хушк нестанд, балки бояд бо тағйирёбандаҳои муҳитӣ, ба монанди намуди хок, усули обварӣ (мағзакнорӣ ё пайпӣ) ва минтаҷаи ҷуғрофӣ мувофиқат дошта бошанд.</p><p>Конжад рӯёнаест, ки бисёр нависҳо дорад ва аз ҷиҳати андозаи тоҳ ва баландии рӯён фарқиятҳои назаррас дорад. Бинобар ин, қонуни доимӣ барои ҳамаи шартҳо вуҷуд надорад, балки бояд аз сатҳи беҳтарин истифода шавад. Мо дар ин ҷо бо таҳлили омилҳои таъсиррасон, ба шумо кӯмак мекунем, то беҳтарин қарорро барои деҳкӯнаки худ қабул кунед. Инчунин ба таҳлили мавзӯи муштарак, ба монанди [ҳамоиши пайпӣ барои як гектар чӣ қадар аст?](https://navar-abyari.ir/%D9%87%D8%B2%D9%8A%D9%86%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%85-%D8%A8%D8%B1%D8%A7%D9%8A-%D9%84%D9%85-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1-%DA%86%D9%82%D8%AF%D8%B1-%D8%A7%D8%B3%D8%AA/) мепароем, то робита байни зерибурзҳои обварӣ ва зичии парваршавӣ равшан гардад.</p><p></p><h2>Сатҳи беҳтарини зичии тоҳ вобаста ба нависҳо</h2><p>Муътабартарин дастурунамуси миқдори боди кунҷит дар ҳектар нишон медиҳад, ки равонҳо чангӣ ҳассосияти баланд доранд ба зичӣ. Барои кунҷит, вобаста ба намудҳои мавҷуд, фосила оддӣ аз 5 то 25 килограмм дар ҳектар тағйир меёбад. Намудҳое, ки донаҳои бузургтар ва равонҳои баландтар доранд, ба зичии камтар ниёз доранд. Аз ҷиҳати дигар, намудҳои зудагирон ва кӯтоҳқад, ки оддӣ барои кабудкунӣ дар минтақаҳои сардҳокиши ё кабудкунӣ байни ду ҳосил истифода мешаванд, метавонанд зичии баландтарро ба худ пайдо кунанд.</p><ul><li><strong>Намудҳои баланд ва донабозоркунанда:</strong> Аз рӯи ҳадди аксар 5 то 7 килограмм бод дар ҳектар. Масофаи байни сафҳо дар ин намудҳо бояд зиёд карда шавад, то тозакии кофӣ ба баргҳо расад ва аз пайдоиши бемориҳои қарачӣ пешгири шавад.</li><li><strong>Намудҳои миёна:</strong> Фосилаи идеалӣ 10 то 15 килограмм. Ин гурӯҳ аксарияти истеъмолкунандагони саноҳиро ташкил медиҳад.</li><li><strong>Намудҳои зудагирон ва кӯтоҳқад:</strong> Метавон то 20 ё 25 килограммро дар назар гирифт. Ин усул бештар барои мақсади боргирии ягон сабзавоти иловагӣ ё кабудкунии тӯлибоязи тобисӣ истифода мешавад.</li></ul><p>Яке аз хатогиҳои маъмул, истифодаи коэффитсиенти табдилдиҳии вазн барои намудҳои гуногун бе назардошти фоизии пайдошавӣ (носути рош) аст. Боди кунҷит, агар солим ва нав бошад, суръати баланди рош дорад, вале дар ситори қадимӣ будан, бояд миқдори боди истифодашавударо бо ҳисоб зиёд кунед. Ин нуқта дар ҳама дастурҳо, монанди миқдори боди чаву ва об дар ҳектар, низ тасдиқ шудааст, ки коэффитсиенти солим бо бод бояд марказӣ дар ҳисобҳо бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کنجد-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر کنجد در هکتار: راهنمای جامع - تصویر 1"/><figcaption>норма посевов на гектар культуры: кунжут</figcaption></figure><p></p><h2>Влияние способа орошения на определение расстояния и количества семян</h2><p>Планирование посева кунjuta сегодня невозможно представить без ирригационной инфраструктуры. Выбор системы ленточного капельного или капельного орошения напрямую влияет на распределение влаги и корневое развитие растений, что позволяет увеличивать норму высева семян. Ленточное орошение очень популярно в широких зонах благодаря низкой стоимости и быстрой реализации. Для принятия обоснованного решения изучение статьи «Сколько стоит ленточное орошение на гектар?» может дать вам полное представление. В системах ленточного орошения обычно расстояние между лентами составляет 40–50 сантиметров, а семена высеваются точно над лентой, чтобы корни быстро получили доступ к влаге.</p><p>Напротив, капельное орошение предлагает большую гибкость в размещении растений. Если использовать двухсторонние капельные линии, можно сократить расстояние между растениями и сохранить количество семян, не допуская чрезмерной конкуренции между растениями. Кроме того, для тех, кто использует междурядьевые посадки с другими культурами, изучение расстояний при ленточном орошении бобовых может предоставить алгоритм для настройки расстояний при смешанном посеве кунjuta и бобовых. Смешанный посев кунjuta с бобовыми или другими бобовыми культурами повышает биоразнообразие и предотвращает повторные заболевания, но требует двойной точности при расчете пространства для каждого растения.</p><h3>Практические советы для механизированного и ручного посева</h3><p>Фарқият дар дақиқии паҳн кардани тоҷри байни дастгоҳҳои механикӣ ва кортиби дасти метавонад дарсади нокомии рӯиданро тағйир диҳад. Дар кортиби механикӣ, маслиҳат дода мешавад, ки аз паҳн кардани тоҷри бо фишори танзимшуда истифода баред, то ки дарозии воқеии фаворӯсиро бартараф кунад. Агар кортибро дасти анҷом диҳед, истифодаи чӯм-пиманда ё метрро, ки дар сафҳо кашида шудааст, кафолати фавари собит байни наъмоҳоро таъмин мекунад. Фаромӯш накунед, ки сунел барои фишори хок ҳассос аст; бинобар ин, чуқури кортиб бояд дақиқан аз 1 то 1/5 сантиметр бошад. Кортиби чуқуртар сабабшавандаи оҳиста шудани рушд ва дар якҷоягӣ нокомии рӯидан мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کنجد-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر کنجد در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Мiqдори тоҷри дар ҳектар парвариши сунел</figcaption></figure><h2>Санҷиши омили иқлимӣ ва хок барои дурдасти тоҷри</h2><p>Хокҳои сангроҳ, ки обдиҳӣ ва retention пасттар доранд, ба зичии тоҷри пасттар ниёз доранд, то ки набатот метавонанд решаҳои чуқуртар партолананд ва аз рутубати зеринави бархӯрд кунанд. Дар хокҳои равғанӣ ва вазнин, метавон аз зичии баландтар истифода бурд, зеро нигоҳдошти рутубат дар решаҳои сатҳӣ беҳтар аст. Инчунин, дар минтақаҳои гарм ва хушк, ки рутубати ҳаво камтар аст, кам шудани зичии тоҷри ва зиёд шудани масофаи наъмоҳо, боиси он мешавад, ки набатот стресси камтар аз сар мегузаронанд ва сифати равған беҳтар нигоҳ дошта мешавад. Ин масъала ҳамчун ҳамсоягӣ бо дигар маҳсулоти деҳқонӣ низ муҳим аст. Агар заминатон бо хоки дуқуъа ё чормағур ҳамсоя бошад, санҷиши раҳнамоҳое, ки <a href="https://navar-abyari.ir/lentil-irrigated-yield-hectare-guide/">Ифтиқори нони обнӣ дар ҳектар</a> метавонад ба шумо кӯмак расонад, то мувозинати манбаъҳои обро дар кортиби пайдарпазир беҳтар фаҳмед, зеро сунел низ ба идоракунии дақиқи даврии об вобаста аст.</p><p></p><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><p>Дар ин қисм мо ба саволҳои такроршуда байни деҳқонон дар бораи ҳисобкунӣ ва амалӣ кардан мепардозем:</p><h3>1. Оё имконият вуҷуд дорад, ки равонро (сезам) бо зичии хеле баланд барои истеҳсоли барг ва реша пардозан?</h3><p>Бале, вале ин кор бештар барои ҳадафҳои ғизои чорводорӣ ё истеҳсоли нахи сабз (green manure) истифода мешавад. Дар ин ҳолат зичии тохм метавонад ба зиёда аз 30 килограмм расад, аммо дарораи тохми сифати баланд умед намоед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کنجد-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر کنجد در هکتار: راهنمای جامع - تصویر 3"/><figcaption>miqdori tohm bar gektar равон</figcaption></figure><h3>2. Чӣ тавр тохми равонро бо системаи обдорӣ-бутташавӣ якҷоя пардозан?</h3><p>Машъақоти бутташавӣро бо пардозии механикии тохм тавсия карда мешавад. Шумо метавонед аз бутташавии дутарафона истифода баред ва тохмро дақиқан дар нуқтаи миёнаи байни ду паҳлуҳои бутташавӣ пардозед, то ки ҳам мунтазми намӣ пурра бошад ва ҳам фазои пардозии оптималӣ дошта бошад. Барои муҳимоти бештар, шумо метавонед ба дастурии комил [пардоши хурмак бо усули обдорӣ-бутташавӣ](https://navar-abyari.ir/%d8%b1%d8%a7%d9%87%d9%86%d9%85%d8%a7%db%8a-%d8%ac%d8%a7%d9%85%d8%b9-%da%a9%d8%a7%d8%b4%d8%aa-%d8%ae%d9%8a%d8%a7%d8%b1-%d8%a8%d8%a7-%d8%b1%d9%88%d8%b4-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8a/) даъо кард, ки принсипҳои монанди ҷойгиркунии тохмҳои хурдро шарҳ медиҳад.</p><h3>3. Дар ҳолати паст шудани сифати тохм, чӣ тағйирот дар миқдори тохм ба вуҷуд меояд?</h3><p>Агар фоизи намоиши тохми шумо аз 80% камтар шавад, бояд миқдори истифодашудаи тохмро бо коэффисиенти (100/ фоизи намоиш) танзим диҳед. Мисолан, агар намоиш 70% бошад, миқдори тохмро 1.42 баробар миқдори стандартиро афзоиш диҳед, то ки пурракунии лозима вуҷуд дошта бошад.</p><h2>Хулоса ва тавсияҳои ниҳоӣ</h2><p>Муайяни дақиқ <strong>Микдори бӯи кишмангоҳ дар ҳектар</strong> Ярро раванди динамикӣ аст, ки ба назорати доимии шароити майдони корӣ, навъи интихобшуда ва инфрасохтори обёрӣ ниёз дорад. Истифодаи ширини обӣ ё қатрӣ на танҳо ҳамчун интихоби бюджетӣ, балки ҳамчун қисми стратегияи гузоштан ба кор карданӣ бояд бошад, то ки намдории якхела ва рушди якхелаи ҷунборҳо кафолат дода шавад. Мо тавсия мекунем, ки пеш аз ҳар гузоштан ба кор намоидаи навро дар майдони худ намунаи хурдро гузаронед ва зичиҳои гунаро дар шароити воқеии худ санҷед. Ин на танҳо хараҷи хатоҳоро кам мекунад, балки барои солҳои оянда ба шумо маълумоти шахсиашуда мерасонад. Дар натиҷа, диққат ба принсипҳои асосӣ ва истифодаи манбаъҳои ҳуҷҷатнок кафолати муваффақияти тӯли муддати шумо дар корҳои ин ҳаробаи қиматрас мебошад.</p>\n<p><strong>Мавзӯҳои вобаста:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%A7%D8%B1%D8%B2%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8A7D8B1D8B2D986 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>， <a href="https://navar-abyari.ir/clover-yield-per-hectare-factors-increase/">clover yield per hectare factors increase</a>， <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b4%d9%86%d8%a8%d9%84%db%8c%d9%84%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Микдори бӯи шабплигоҳ дар ҳектар: раҳнамоии ҷамъбаст</a></p>','Сеҳҳати бобаи кунҷид дар як гектар: Равуши асосии ғунҷиднокӣ','Дар ин мақола усулҳои дақиқтарини ҳисоб кардани миқдори бехи сесам дар гектар, таъсири нависҳо гуногун, шароити замин ва усулҳои муосири обёрӣ бар зичии ҷӯр кунӣ баррасӣ мешаванд, то ки деҳқонон бо истифода аз маълумоти илмӣ, хавфи нобудшавии бехро коҳиш дода, маҳсулоти якхела ва амалӣ дошта бошанд.','publish','closed','closed','boba-i-kunjid-dar-heyat',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
