INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима ба робитаи ороиш бо қатра ва саломатии паприка</h2>\n<p>Паприка яке аз ҳосилҳои серҳассоси шабакагӣ ва озод ба ҳисоб меравад, ки аз сабаби пӯсти нафӯс ва сохтори дарахтӣ, барои баҳсубӣ ва бемориҳои қарозӣ ва бактериявӣ дучор мемонад. Истинод ба <strong>ороиш бо қатра</strong> на танҳо манбаи асосии таъмини об, балки асбоби қудратнок барои идоракунии ризошарофии решаҳо ва кам кардани хатари пайдо шудани бемориҳо ба ҳисоб меравад. Дар ин дастраҳо, мо ба баррасии дақиқи зарарзанандагон ва бемориҳои паприка дар ороиш бо қатра мефаҳмонем, то ки кӯҳнакзорон бо танзими дақиқи параметрҳои орош, одамони худро ба ҳадди ақалл расонанд.</p>\n\n\n\n<h2>Таъсири системаҳои оборӣ ба пешгирии бемориҳои қурбӣ ва бактериявӣ</h2>\n<p>Яке аз муҳимтарин омили хатарбар барои паприка нигоҳ доштани намии баланди барг ва хок аст. Дар обори боронӣ ва шатрӣ, намӣ дар сатҳи барг зиёд мешавад, ки шароити муносиб барои паҳншавии қурбӣҳо, монанди антракноз ва бонги, фароҳам меорад. Баръакс, обори бачабачаӣ тавассути расонидани об бевосита ба минтақаи реша, намии сатҳи баргро кам мекунад ва давраи мувофиқро барои пайдоиши беморӣ маҳдуд менамояд. Илова бар ин, идоракунии дурусти ин система ниёз ба эҳтиёт дорад, зеро расониши нокофики об метавонад фишори хушкӣ эҷод кунад ва ҳосилнокии решагии растаниро ба бемориҳо зиёдтар мекунад.</p>\n<h3>Вайроншавии гул ва мевуҳо</h3>\n<ul>\n<li><strong>Вайроншавии хокистарӣ (Botrytis):</strong> Ин зангвор дар ҳарорати хунук ва намии баланд фаъол аст. Оборӣ бо қатраҳо, бо шарти парҳиз аз обори беш аз ҳад, аз шустани зарфҳои сафед бар мевояҳо пешгирӣ мекунад.</li>\n<li><strong>Фасидани нарм (Sclerotinia):</strong> Ин беморӣ аз хок гузошта мешавад. Истифодаи нӯҳои нипи пластирон бо фишори назоратшуда метавонад аз парҳези хок бо қатраҳои об пешгирӣ кунад, гарчанде ки дар паприка одатан обори дар сатҳи замин тавсия дода мешавад, вале назорати фишор аз фасидани минтақаи сохҳои асосӣ пешгирӣ мекунад.</li>\n</ul>\n<h3>Бемориҳои решаҳо</h3>\n<p>Бемориҳое чун фасидани реша (Fusarium ва Pythium) ҳамеша дар хок мавҷуданд. Обори қатрагӣ метавонад тавассути эҷоди микроҳавогирии мувофиқ, аз бадағар шудани таъсири оксиген бар решаҳо пешгирӣ кунад. Агар обори бо шидати баланд иҷро шавад ва дренаж заиф бошад, решаҳо дар об ғарқ мешаванд ва зуд ба бактерияҳои фасидшаванда ҳамла мекунанд. Бинобар ин, танзими вақти давраи обори, то ки хок имконияти nafas гирифта бошад, муҳим аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-پاپریکا-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های پاپریکا با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation пәприка</figcaption></figure>\n\n\n\n<h2>Мудиряти зараррасонҳои хӯроккӯн ва сӯрохкунанда бо нӯҳои нип</h2>\n<p>Афатҳои паприка ба ду гурӯҳи асосӣ тақсим мешаванд: афатҳои мӯшкӯб (масалан, шитҳои сабз ва маро, афатҳои сафед ва трипс) ва афатҳои сохтнокунанда (масалан, шигангҳо). Обиёбӣ дар шакли қатрагӣ ба таври мустақим афатҳоро нест намедиҳад, вале ба рафтори онҳо таъсир мерасонад. Ғалағудаи баланди фазои зери ниҳоки пӯшанд, ки баъзан аз саршори нӯриҳои дрип ба вуҷуд меояд, метавонад муҳити муносиб барои шитҳо бошад. Аз тарафи дигар, стресси обӣ ба истеҳсоли гормонҳои стресс дар раста оварда мерасонад, ки метавонад лаззати баргҳоро барои ҳашарот ҷозибтар қарор диҳад. Барои афатҳои сохтнокунанда ба монанди шиганг, зарари расидан ба пӯсти борикӣ меваҳо дарвозаро барои агентҳои бемориза кушоӣ медиҳад. Дар ин ҷо, ноқисии нӯри обиёбӣ ва пешгирӣ аз шикастҳои механикӣ, ки ба паҳншавии об ба сати мева ё узв оварда мерасонад, муҳим аст. Агар нӯри дрип солим бошад, тамоси мустақими об бо мева ва баргҳои поёнӣ камтар мешавад ва дар натиҷа, сати тамос бо шадидкунӣ ва пӯсидагиҳои иловагӣ кам мешавад.</p>\n<h3>Нақши сифати об дар паҳншавии ифлосшавӣ</h3>\n<p>Оберо, ки дар обиёби қатрагӣ истифода мешавад, метавонад дармонандаи бактерияҳо ва сабулонҳои бемориза бошад. Агар обиёбӣ бо оби лоғубиёбӣ ё чӯби ифлос иҷро шавад, ин агентҳо тавассути қатраҳо мустақиман бо решаҳо ё узвҳои поёни раста тамос мекунанд. Бинобар ин, тозакунии об ва истифодаи филтбрҳои оптикӣ ва механикӣ дар даромади системии қатрагӣ, як қадами ҳатмӣ дар идоракунии афатҳо ва бемориҳои паприка бо обиёби қатрагӣ аст. Филтркунии об инчунин даргирии қатраконҳоро пешгирӣ мекунад, ки ба тақсимоти натамомони об ва пайдоиш доштани дарахтҳои хушк дар ғалағуда оварда мерасонад.</p>\n\n\n\n<h2>Мулоҳизаҳои амалӣ барои кишоварон</h2>\n<p>Барои баҳриши максималӣ аз системҳои обиёбӣ дар идоракунии саломатии паприка, риояи асосҳои зерин зарур аст:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-پاپریکا-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های پاپریکا با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation паприка</figcaption></figure>\n<ol>\n<li><strong>Идоракунии ҳарорати ҳодисаҳои микроскопӣ:</strong> Ориғии қатраҳо гармидаи атрофи решаҳоро устувор нигоҳ медорад. Дар ҳавои сард ин устуворӣ аз шикасти решаҳо пешгирӣ мекунад ва дар ҳавои гарм гармии зиёдатии хокро коҳиш медиҳад.</li>\n<li><strong>Танзими EC ва pH об:</strong> Зичии моддаҳои моеъ ва кислоталики об дар ҳолати ориғӣ таъсири мустақим ба рушди гирдиҳаи реша дорад. pH тақрибан 6.0 то 6.5 банди беҳтарин барои дастрасии моддаҳои ғизоӣ ва заифкунии бактерияҳои патогенӣ мебошад.</li>\n<li><strong>Корзирии рӯякро пӯшидан ва идоракунии дарахтонҳо:</strong> Нӯри тайп бояд дақиқан дар хати корзӣ ҷойгир бошад, то аз ориғии минтақаҳои дарахтони зараровар пешгирӣ шавад. Дарахтонҳои зараровар манбаи муҳим барои пинҳони заъфи пиперинҳо мебошанд.</li>\n<li><strong>Невонгунии дурусти нӯр:</strong> Истифодаи нӯрҳои тайп бо қутри дохилӣ мувофиқ (одатан 16 то 18 миллиметр) ва сӯрохиҳои мувофиқ барои пиперинҳо омили ҷараёни оҳистаеро эҷод мекунад, ки намро якхела мекунад. Барои маълумоти бештар дар бораи техникавӣ <a href="https://navar-abyari.ir/%d9%87%d9%85%d9%87-%da%86%db%8c%d8%b2-%d8%af%d8%b1%d8%a8%d8%a7%d8%b1%d9%87-%d9%85%d8%b2%d8%a7%db%8c%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d9%be%d9%84%d8%a7%da%a9%d8%af%d8%a7%d8%b1/">Ҳама чиз дар бораи афзалиятҳои нӯри тайпи пластики</a> Шумо метавонед таҳқиқ кунед.</li>\n</ol>\n<h3>Ҷадвали муқоисаи таъсири обкорӣ тавассути тамчи-дам (қатра) ба муҳимтарин зараррасонҳо ва беморҳо</h3>\n<table>\n<thead>\n<tr><th>Зараррасон/Беморӣ</th><th>Ҳолат дар обкории анъанавӣ</th><th>Ҳолат дар обкорӣ тавассути тамчи-дам (қатра)</th><th>Тавсияи амалишуда</th></tr>\n</thead>\n<tbody>\n<tr><td>Фасидану дурӯблудан (фузариум)</td><td>Алгории баланд ба сабаби нишаста будани доимии об</td><td>Коҳиш назаррас бо идоракунии даври оборӣ</td><td>Истифодаи филтр, pH мувофиқ</td></tr>\n<tr><td>Мулди сабз</td><td>Коҳиш ба қисмҳои хушк‌тар</td><td>Мулди зери дарахт бо ризиши нӯри</td><td>Таъмири нӯри, набудани ризиш</td></tr>\n<tr><td>Мулдпаст</td><td>Заҳмат бевосита</td><td>Кам кардан зарар тавассути тоз будани сатҳ</td><td>Нобудкунии кимиёвии поёндатал</td></tr>\n<tr><td>Фасодшавии мева (ботритис)</td><td>Дағолат дар намии баланд</td><td>Идоракунии осон бо вентилятсия</td><td>Идоракунии ҳарорат ва намии ҳаво</td></tr>\n</tbody>\n</table>\n<h2>Саволҳои зудпурсида (FAQ)</h2>\n<h3>Оё обириши босарчӣ метавонад аз фасодшавии меваи паприка пешгирӣ кунад?</h3>\n<p>Бале, аммо шарт онест, ки системаи обории (абории) нобаҳҳо надорад. Даргирии об бо мева ё кабудҳои поёнӣ метавонад сабаб шуда, гирякуниро ба вуҷуд орад. Лавҳаҳои дрилӣ бо сифати мувофиқ ва насби дуруст ин хатарро ба ҳадди ақал меоранд.</p>\n<h3>Фавоси кадом барои лавҳаҳои дрилӣ барои пеприка мувофиқ аст?</h3>\n<p>Одатан, масофаи 20 то 25 сантиметр аз гӯзи асосӣ тавсия дода мешавад. Барои маълумоти бештар дар бораи масофаҳои стандартӣ дар партовкуни, шумо метавонед ба <a href="https://navar-abyari.ir/sugar-beet-row-spacing-standards/">масофаи сафҳои шакарпӣ</a> то равонашӣ, гарчанде ки принсипҳои шабоҳ дар пеприка низ иҷро мешаванд.</p>\n<h3>Оё дар обории қатрагонӣ метавон токсикҳои кимиёвиро истифода бурд?</h3>\n<p>Бале, формулятсияҳои махсус барои обории қатрагонӣ (финокиятсия) вуҷуд дорад, ки токсикҳоро ба ростанӣ мефиристад. Ин усул барои мубориза бо зараррасонҳое, ба монанди гулҳои равонӣ, хеле самаранок аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-پاپریکا-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های پاپریکا با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation пеприка</figcaption></figure>\n<h3>Таъсири фосфаи ҳосилкунӣ ба паҳншавии зараррасонҳо чист?</h3>\n<p>Дар болғори (паприка) маҳдуд будани фосфаи ҳосилкунӣ боиси камшавии ҳавопаҳлӯӣ мегардад. Дар обудкунии сачаккашӣ, агар ҳавопаҳлӯӣ кам бошад, намёкӣ бозмонда аз ҷунбонаҳои сачаккунӣ наметавонад бухор шавад. Фосфаи мувофиқ ба ҳавопаҳлӯӣ кӯмак мерасонад. Барои омӯзиши усулҳои ҳосилкунӣ, <a href="https://navar-abyari.ir/corn-strip-tape-spacing-forage-corn/">Фосфаи ҷунбонаҳои сачаккунӣ барои ҷугорои ғӯлӣ</a> метавонад намунае аз принсипҳои фосфакуноӣ бошад.</p>\n<h2>Хулоса ва дидбони оянда</h2>\n<p>Муташаккули зараррасониҳо ва бемориҳои болғори (паприка) бо обудкунии сачаккашӣ, як равиши мушаххас аст, ки ҳам ба зиёд шудани ҳосил ва ҳам ба кам шудани истифодаи моддаҳои заҳрнок кӯмак мерасонад. Бо назардошти ҳассосии баланди ин маҳсулот ба стрессҳои муҳитӣ, диққат ба тафсилоти системаи обудкуни аз интихоби ҷунбонаи сачаккунии мувофиқ то танзими pH ва EC об, муайянкунии муваффақияти мезробона мебошад. Деҳқонони муваффақ онҳоянд, ки бо назорати дақиқи вазъиятҳои замин ва ҳарорат, бо барномасозии дуруст, аз ҷунбонаҳои сачаккунӣ ҳамчун воситаи идоракунии беморӣ истифода мебароранд. Ин равиши устувор на танҳо хароҷоти кимиёвиро кам мекунад, балки сифати меваҳои болғори (паприка)-ро дар миқёси тавозунафӣ беҳтар мекунад. Бо назардошти ин маълумотҳо, омӯзиши мақолаҳои алоқаманд монанди <a href="https://navar-abyari.ir/bell-pepper-yield-per-hectare-tajik-farmers/">Ҳосили болғори (паприка) дар гектар барои деҳқонони Тоҷикистон</a> метавонад дониши амиқтарро дар бораи пурзӯрии болғори (паприка) дар шароити гуногун бахшед.</p>','Заҳратҳо ва бемориҳои паприка омодаи обёрӣ ангуштонӣ','Дар ин мақола, мо бо тафсилоти пурра таҳлил мекунем, ки системаи оборӣ ба қатра чӣ гуна бо пешгирии ҳашарот ва бемориҳои поприкӣ ҳамкорӣ мекунад. Аз идоракунии пӯли занбӯруқӣ то назорати ширкаҳо ва маслиҳатҳои амалӣ барои зиёд кардани хуред.','publish','closed','closed','zahrat-ho-va-bemori-hoyi-paprika-obori-darahaai',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
