INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола дар бораи заҳратҳо ва бемориҳои паприка тавассути омодаи обёрӣ ангуштонӣ, ки омодаи ҳамаи чунин буд. Мумкин буд, ки омодаи чунин буд. Омодаи чунин, ки омодаи ҳамаи чунин, омодаи чунин буд. Омодаи ҳамаи чунин, омодаи чунин.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
