INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Мутахассисони кишоварзӣ роҳнамоии пурра ва амалиро дар бораи кардани ғундӯз (шҳ) бо усули обёрӣи қатқатӣ ва навар пешниҳод мекунанд. Ин методҳо ҳаҷми истифодаи обро кам карда, истеҳсолро зиёд намуда, барои деҳқонони таҳқиқотии тоҷик муносибанд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
