INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Каллукӣи камиллини дар натиҷаи одамон барои истифодаи бисёртоҷаҳонаи дорӣ ва ғизоӣ дар солҳои охир дар байни деҳқонон маъмултар шудааст. Мусоидатҳои асосии ин каллукӣ ҳифзи мувозинати рутубати хок ва пешгирии парешни гулҳо мебошад. Истифодаи <strong>обёрии қатрагонӣ</strong> ё риштагиҳо, роҳи амаликунӣ барои ҳалли ин мушкилӣ мебошад. Дар ин мақола, масъалаҳои монанди ҷойгиркунии сатҳҳо, мухтисори замина ва саҳифаи вақтӣ барои обёрӣ дар тартиби дақиқ баррасӣ мешаванд, то ки деҳқонон бо камтарин зарари ва хосилияти баланд маҳсули ниҳоиро таҳвир кунанд. Ин системҳо бо роҳи ҷойгиркунии об дар минтақаи решаҳо стресси обро камтар мекунанд ва шароитро барои рушди якхелаи наботот фароҳам меоранд, ки дар усулҳои анъанавии обёрӣ монанди абортонӣ номумкин аст.</p><h2>Ҷойгиркунии ва тайёркунии замина барои кортиз</h2><p>Барои истифодаи камтарин қувваи мардумӣ ва машиноамолидҳо, ҷойгиркунии сатҳҳои камиллини аҳамияти зиёд дорад. Фазои байни сатҳҳои асосӣ одатан байни 50 то 60 сантиметр муайян карда мешавад, то ки ҳавокишмии мувофиқ байни буттаҳо ба амал ояд ва ҳаракати ҳаво ба камшудани паҳншавии бемориҳои қарағози мусоидат кунад. Самти ҷойгиркунии сатҳҳо бояд аз рӯи самти боради доимии шамол ва шароити зироатии минтақа танзим шавад. Инчунин, мухтисори замина нақши муҳимро дар фаъолияти системаи обёрӣ мебозад. Марҳилаҳои насби риштагиҳо ниёз ба мухтисории якхелаи замина дорад; чунки ноустувории мухтисор боиси хориҷшавии система аз хат ва зиёдшудани истиноси энергияи помпа мешавад. Мухтисори уфуқӣ зиёда аз 3% метавонад боиси ҷамъшавии об дар нуқтаҳои поёнӣ ва хушк мондани нуқтаҳои болоӣ гардад, ки боиси рушди нехелаи наботот мегардад. Бинобар ин, санҷиши дақиқи замина пеш аз кортиз, қадами аввалин дар муваффақияти лоиҳа мебошад. Илова бар мухтисор, намуди хок низ дар интихоби намуди система ва масофаи ҷойниширҳо таъсиррасон аст; дар хоки сабук бо ҳодисаи пастдории об кам, масофаи ҷойниширҳо бояд зиёдтар бошад, то аз абортонии решаҳо пешгирӣ карда шавад, дар ҳоле ки дар хоки вазнин, масофаҳои хурдтар мувофиқтаранд.</p><p>Қабл аз калонкунӣ, хок бояд аз ҷиҳати моддаҳои хунукӣ ва pH баробар бошад. Шурӯш беш аз меъёр метавонад боиси сӯзидан пӯстҳои баргҳо дар рахи кампелина шавад. Истифодаи тағирдиҳандаҳои гӯгӣ ё омехта бо компост дар беҳдошти хок дар заминаи шӯр раванди барқароркунии хокро суръат мебахшад. Таҳлили дақиқи хок пеш аз калонкунӣ ба деҳқон имкон медиҳад, ки ғизои мувофиқро аз рӯи ниёзҳои махсуси хок истифода барад ва аз бознӯшии аз заришҳои кимиёвӣ худдорӣ намояд. Ин қадам асоси системаи устувор аст, ки пас аз ин тавассути идоракунии обӣ пурра мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کاملینا-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت کاملینا با آبیاری قطره‌ای - تصویر 1"/><figcaption>Usulҳои kалонkunӣ drip crop irrigation schedule Kameliina</figcaption></figure>\n<div></div><h2>Nabar-i drip va идораkунӣи rутуби bафти (texture)</h2><p>Nabar-i drip barои доштани кучукӣ дар шакли пораҳо, rутубатро бевосита ба ҳудуди асосии реша интиқол медиҳад. Ин хусусият боиси шудани беранг будани рӯи хокӣ мешавад ва хатари пайдо шудани моҳӣ ва қарҷ дар баргҳои поёнӣ кам мешавад. Барои ҳар як сатр, истифода аз набар бо гардиш 16 миллиметр ва фаъолият 20 сантиметрӣ тавсия дода мешавад. Интихоби гардиш ва суръати дуруст, зарури ҳисоботҳои дақиқро барои таъмини ниёзҳои рӯзи об дар ҳолати ҳадди баланди истифода мебошад. Ҳисоботҳои нақсон мумкин аст ба нокифодии об оварда расонад, дар ҳоле ки суръати беш аз ҳад боиси партофтани захираҳо ва табҳи решаҳо мегардад. Инчунин, барои таъмини умри кории системаи система набарҳои гилзери метавонад муқобимат ба фишори корӣ ва фишори муҳит бошад. Дар шароити гарми ҷаҳонӣ, диққат ба ҳарорати кории насос ва набар барои пешгирӣ аз тағироти шакл зарур аст.</p>\n<h3>Сиёсати обкунӣ дар марҳилаҳои рушд</h3><ul><li><strong>Марҳилаи таринг (ҳафтаи якум):</strong> Обкунӣ хеле чунқу ва хеле сершумор (ду маротиба дар рӯз) барои пур шудани фазои холӣ барои решаҳо. Дар ин марҳила, решаҳо хеле лабик мебошанд ва тобоварии бори об хеле паст доранд.</li><li><strong>Марҳилаи рушд ва инкишоф:</strong> Кам кардани шумораи борбории ба як бор дар як рӯз бо ҳаҷми бештар. Мақсади асосӣ дар ин марҳила таъмини об барои афзоиши зуд биомассаи нишаст аст.</li><li><strong>Марҳилаи гулбардон:</strong> Аз стресси шадиди қурав парҳез кунед. Партоби тухмҳо дар ин марҳила аксар вақт бо сабаби камбудии об ба вуҷуд меояд. Собит кардани намӣ дар ин марҳила муҳимтарин омили шаклигирии дона аст.</li></ul><p>Азбаски системаҳои борбории рӯлона бо фишорҳои паст кор мекунанд, лозим аст, ки бо риояи қоидаҳои дурусти насб, аз воридшавииоби иловагӣ ба бستر пешгирӣ кунед. Истифодаи паргҳои фишоршикан дар сари лӯлаҳои нақлиётӣ аз коҳиши фишор ва нобаробарии даромад дар тӯли қатор пешгирӣ мекунад. Ин танзимот бояд ба таври мунтазам аз ҷониби мутахассиси борбории санҷида шаванд, то ҷинобат аз профили даромади дилхоҳ пешгирӣ шавад.</p>\n<div></div><h2>Ҷадвали барвақткунии борбории (Irrigation Schedule)</h2><table><thead><tr><th>Марҳилаи нишаст</th><th>Фосилаи вақтӣ</th><th>Ҳаҷм ба ҳар сарҳад</th><th>Сабаби ихтисосӣ</th></tr></thead><tbody><tr><td>Навбуд</td><td>2 маротиба дар рӯз</td><td>20-30 литр</td><td>Нигоҳдории намнокии атрофи нав</td></tr><tr><td>Рӯиш</td><td>Ҳаррӯза</td><td>50-60 литр</td><td>Изоф кардани суръати рушди шушуб</td></tr><tr><td>Гулҳое, ки дар ҳоли ташкил мебошанд</td><td>Ҳар 2 рӯз</td><td>70-80 литр</td><td>Ҳифзи гулҳо аз партобиш</td></tr></tbody></table><h3>Идоракунии озуадоҳӣ бо системаи капель</h3><p>Истифодаи омехтаи озуаи маҳлулӣ бо оборишӣ ва обориши маҳлулӣ яке аз бартарии ин система мебошад. Истифодаи озуаҳои нитрогенҳо дар ибтидои давра ва зиёд кардани фосфат дар вақти гул кардан самаранокии системаро баланд мебардорад. Мисли он, ки дар <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b4%d8%a7%d9%87%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори тоҳи шӯбиш дар гектар: омилҳои таъсиррасон ва роҳҳои беҳтаркунӣ</a> Пояз меъмӯришӣ аст, ки диққат ба консентратсияи нӯшокӣ барои пешгирии сӯхтани сабзаҳо муҳим аст. Аз ҳадди воқеӣ таранҷубуришавии нӯшокӣ, бидуни ҳосилнокии матлуб, барои оморро зиёд мекунад. Инчунин, назорати pH-и маҳлули нӯшокӣ дар системаи обёрӣ барои пешгирии ҷамъшавии намакҳо дар нақбҳо зарур аст. Ин раванд бояд ҳар ҳафта аз ҷониби олимони фитотехникӣ иҷро шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کاملینا-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت کاملینا با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои кӯмакии обёрӣ барои ғаллоҳӣ ва нақши ғаллоҳии кӯмакӣ ва ҷадвали обёрӣ ва ғаллоҳии Куманина</figcaption></figure>\n<h2>Нуктаҳои амалӣ барои киштҳои калон</h2><ol><li>Истифодаи филтри мувофиқ (80-120 ғапҳо) барои пешгирии ғурӯбшавии нақбҳои биндакӣ. Сифати филр таъсири мустақим ба умри фоиданоки биндакҳо дорад.</li><li>Пӯшидан компии пайдоиш аз қаторӣ ва плавтик барои кам кардани партоби об. Ин кор инчунин аз раштани чарбои ғамисӣ, ки рақибони манбаъи ғизо мебошанд, пешгирӣ мекунад.</li><li>Нозорати фишори хориҷӣ аз помпа: пастшавии фишор нишонаи ғирҳамшавии система мебошад. Сабти рӯзонаи фишори дарахшавӣ ва хориҷшавии система ба ёфтани пеш аз вақти пастшавии коркарди система кӯмак мекунад.</li></ol><p>Шиносоӣ бо шароити ободии минтақа зарур аст; масалан, дар шароити шабҳои хунук, таҳдиди занг дорад. Дар ин шароит, обёрӣ бояд субҳҳо иҷро шавад, то он ки ором то офтобпад хушк шавад. Ин рӯйкард ба идоракунии монанди <a href="https://navar-abyari.ir/%d8%aa%d9%86%d8%a7%da%98-%d9%82%d8%b5%db%8c%d9%84-%d8%ac%d9%88-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҷадвали миқдори ғаллоҳи ҷадвалӣ барои ғаллоҳи ҷадвалӣ: омилҳои таъсиркунанда + усули зиёдкунӣ</a> ки даромад ба назорати дақиқи шартҳои муҳитӣ вобаста аст. Маҷмӯи маълумотҳои обу ҳаво бо нақшаи оборӣ беҳтарин натиҷаро ба бор меорад.</p>\n<h2>Саволҳои маъмул (FAQ)</h2><h3>Оё шиназҳои даринӣ барои тамоми минтақаҳои иқлимии гирифтани капинда мувофиқанд?</h3><p>Бале, аммо дар минтақаҳое, ки шамолҳои қавӣ ҳастанд, ҳатман асос бояд бо тӯр ҳимоя карда шавад, то шиназ пучид навад. Инчунин, дар минтақаҳои хеле намноки бештар, бояд диққати бештар ба каноркунии асос гурезонида шавад, то аз тобобандии доимӣ пешгирӣ карда шавад.</p><h3>Чӣ тавр аз сӯхтани шиназ дар натиҷаи рӯшноии қавӣ пешгирӣ мекунем?</h3><p>Шиназҳо бояд 2 то 3 сантиметр дар зери сатҳи хок ё пошак ҷойгир бошанд, то бевосита ба UV нашаванд. Агар шумо аз пошаки кӯфуршуда истифода мебаред, исбот кунед, ки пошак монеъи расидани рӯшноии бевосита ба сатҳи шиназ нест.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-کاملینا-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت کاملینا با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule капинда</figcaption></figure>\n<h2>Хулоса</h2><p>Сохтори методиҳои муосири ободори заминҳои деҳқонӣ нишон медиҳад, ки самаранокӣ пурра танҳо бо назорати дақиқи решаҳо имконпазир аст. Амалӣ намудани принсипҳои насб, танзими шидат ва таъдими ободорӣ дар марҳилаҳои ҳассоси рӯянда, калиди дастӣ ба меҳвари якнавоқ ва сифатнок аст. Барои дарки беҳтари принсипҳои тарҳрезии системҳои ободорӣ дар ҳар гектар, омӯзиш <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B0%D8%B1%D8%AA-%D8%B9%D9%84%D9%88%D9%81%D9%87%D8%A7%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8B0D8B1D8AA D8B9D984D988D981D987D8A7DB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a> танзӣм мешавад. Ҳамчунин, барои деҳқононе, ки марҳаматманданд тафосилиро бо дигар маҳсулот мутақобил кунанд, раҳнамоии <a href="https://navar-abyari.ir/pepper-drip-tape-irrigation-guide-tajik-farmers/">pepper drip tape irrigation guide tajik farmers</a> манбаи дигари фойдевар аст, ки нуқтаҳои муштарак ва хусусии ободории қатравашаклро шарҳ медиҳад.</p>\n[[[IMAGE_3]]}\n<p><strong>Маводи вобаста:</strong> Марҳилаҳои насби наварҳои тип, методиҳои муосири ободори заминҳои деҳқонӣ</p>','Пурра дастури ғарофӣ: Кашт кардани сабзи ғарофӣ бо обёрӣи қатрагӣ','Камелина як расаи ниёзманд ба идоракунии дақиқи рӯшноӣ аст. Дар ин дастурамал, усули беҳтарини ғалтак, асосҳои кори нӯри тиб ва jadвали вақти оирибарӣ мувофиқи марҳилаи рушди раса баррасӣ карда мешавад, то самаранокии оби ва сифати ниҳоии маҳсул баланд шуда бошад.','publish','closed','closed','rasid-hisobi-koshish-komelina-obari-qatragi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
