INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дастури муфассал оид ба кашти сабзи ғарофӣ бо истифода аз технологияи муосири обёрӣи қатрагӣ (drip irrigation). Омӯзиши усулҳои амалии кӯмаконда ба зиёд кардани самаранокии ҳосил, кам шудани сарфҳои об ва ҷиҳатҳои техникӣ.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
