INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи лентаи тамғакушӣ барои обёрӣ кардани сабзавоти киви</h2>\n<p>Сабзавоти кивӣ, ҳамчун парвариши муҳим дар бозорҳои кишоварзӣ, барои расидан ба беҳтарин сифат ва вазн ба шароити дақиқи обёрӣ ниёз дорад. Яке аз роҳҳои беҳтарин барои обёрӣ кардани ин мева ва сабзавот истифода аз системаи <strong>лентаи тамғакушӣ</strong> (Drip Tape) мебошад. Ин система аз лентаҳои резинии пластикӣ иборат аст, ки сӯрохҳои хурди барои интиқоли обро дорои мебошанд. Дар бахшҳои оянда, мо ба нуқтаҳои асосии нигоҳубини сабзавоти кивӣ бо лентаи тамғакушӣ диққат медиҳем, то самаранокии умумии система нигоҳ дошта шавад ва сифати маҳсулоти охирин таъмин гардад. Ин равиш на танҳо истеъмоли обро ба ҳадди ақал мерасонад, балки тақсимоти якнавокши рутубатро дар минтақаи ризо нигоҳ медорад, ки барои пешгирии вайроншавии ризо ва кам кардани стресси гармии сабзавоти кивӣ ҳаёт аст. Интихоби ин усули обёрӣ бояд бо иқлими маҳаллӣ ва намуди хок мувофиқат кунад, то беҳтарин самаранокӣ ба даст оварда шавад. Кишоварзони муваффақ ҳамеша пеш аз оғози фасли парвариш, нақшаи дақиқро барои ҷойгиркунӣ ва тартиби обёрӣ татбиқ мекунанд, то аз ихроҷи захираҳо пешгирӣ намоянд. Инчунин, дарки амиқ аз физиологияи олии сабзавоти кивӣ ва ниёзҳои вақтии он ба об ва ғизо қобили асосии танзими системаи лентаи тамғакушӣ мебошад.</p>\n<h3>Муҳимтарин хусусиятҳои лентаи тамғакушӣ барои сабзавоти кивӣ</h3>\n<p>Интихоби намуди лентарока барои карп ғамори муҳим аст. Лентарокаҳо радиусҳои гуногун аз 13 то 16 миллиметр доранд. Барои карп, ки решаҳои он шӯр (кам-оҳанг) аст, одатан лентарокаи 16 миллиметр афзаладӣ мешавад. Ин система тавассути паҳн кардани оби рост ба минтақаи решаҳо ба зиёдшудани фоли ҳосил меоряд ва аз хавфи бемориҳои баргҳо пешгирӣ мекунад. Диди девори лентарока ва намуди полимери, ки барои сохтани он истифода шудааст, бевосита ба тобиш ва устувории лентарока дар муқобили фишор ва ҷунбиш таъсир мерасонад. Лентарокаҳои сифатнок тавозуннокии ҳаҷми даромадро дар давоми умри фолии худ нигоҳ медоранд, ки барои ҳосилоти ҳассос, ба мисли карп, аҳамияти дучанд дорад. Инчунин, шифофии нисбати лентарокаҳои стандартӣ ба деҳқон имконият медиҳад, ки дар боздидҳои муқаррарӣ аз дохили лентарока ва вуҷуди ниқобҳои ибтидоӣ огоҳ бошад.</p>\n\n<h2>Тарқом ва афзоиши карп бо системаи чаниқии лентарока</h2>\n<p>Афзоиши идеалии карп ба назорати дақиқи миқдори об таваҷҷӯҳ дорад. Лентарока метавонад ин назоратро хуб таъмин кунад. Дар ин қисмат ба муҳокими <a href="https://navar-abyari.ir/%d9%86%da%af%d9%87%d8%af%d8%a7%d8%b1%db%8c-%d9%88-%d9%85%d8%af%db%8c%d8%b1%db%8c%d8%aa-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%aa%db%8c%d9%be/">Нигоҳубини ва идоракунии лентарокаи обёрӣ</a> мегузорем, ки дар баргирӣ тартиб додани фишори мувофиқ ва пешгирии маҳкамшавии лентарокарост. Идоракунии дурусти фишор бояд дар тамоми давоми ҳосилот пайгушӣ шавад, зеро паст шудани фишор метавонад боиси кам шудани ҳаҷми даромад дар охири шланг гардад ва боиси паҳнонашавии нодуруст шавад. Дар ин самт, истифода аз вентилҳои танзими фишор дар оғози система ва метраҳои ҳаҷмонбар барои назорати хӯрӯҷ тавсия дода мешавад. Ин тадбирҳо ба он оварда мерасонад, ки карп дар тамоми марҳалаҳои афзоиш, хусусан марҳилаи ташаккули сар, ба оби кофӣ дастрасӣ дошта бошад ва аз фишорҳои шадиди рутубат пешгирӣ шавад, ки боиси сахтшудани баргҳо мегардад.</p>\n<h3>Барномасозии обёрӣ бо мутобиқат ба фасл</h3>\n<p>Иловае лозима барои салат дар фаслҳои гуногун тағйир меёбад. Дар аввалии намоиш ба лозима камтар лозим аст ва бояд аз намунаҳои банди капиллярӣ истифода баред, то рӯишҳо хуб ташаккул ёбанд. Дар ниҳоъ, махсусан ҳангоми ташаккули сари салат, намоиши зиёдрӯз ва мутамадди муҳим мешавад. Истифодаи ҷадвали зерин метавонад ба шумо дар лоиҳабардори дуруст кӯмак расонад. Танзимоти намоиш бояд бо ҳарорати ҳаво ва миқдори испарение-таъминот (ET) ҳудуд мутобиқ бошад. Дар рӯзҳои хеле гарм, сони намоиш зиёд мешавад, аммо давомнокии ҳар як сессия кам мешавад, то ки хуниролуди хок пешгирӣ шавад. Ин мувозинати майда, бевосита ба оромӣ ва ширинии салат дар бозор таъсир мерасонад ва аз пайдоиши дарахши бунедар баргҳо, ки нишонаи стресси об аст, пешгирӣ менамояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-کاهو-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری کاهو با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>нигоҳубини банди намоиши салат</figcaption></figure>\n\n<table>\n<tr><th>таъсири банди намоиш</th><th>тавсияҳои амалӣ</th></tr>\n<tr><td>дави оқими мувофиқ</td><td>Барои салат, дави банди намоиш дар нақшаи 2 то 4 метри мукааб дар соат мувофиқ аст.</td></tr>\n<tr><td> masофа байни бандҳо</td><td>Masофаи 50 то 60 сантиметрӣ байни ду банди намоиш беҳтарин ҳолат аст.</td></tr>\n<tr><td>Дарораки замин</td><td>Калаба сабзи кӯтоҳ мекунад; лӯлаи шӯрӣ бояд дар сатҳи замин ҷойгир шавад.</td></tr>\n</table>\n<p>Барои маълумоти бештар дар бораи <a href="https://navar-abyari.ir/%D8%B6%D8%AE%D8%A7%D9%85%D8%AA-%D8%A7%DB%8C%D8%AF%D8%B9%D8%A7%D9%84-%D8%AC%D8%AF%D8%A7%D8%B1%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D8%AA%DB%8C%D9%BE/">ғафсӣ ва андозаҳои шӯрӣ</a>шумо метавонед ба манбаи оилавӣ пайваст шавед. Ин маълумот кӯмак мерасонед, то фишори мувофиқро барои ҳар хат интихоб кунед. Инчунин санҷиш барои мубориза бар зидди қуллаи оилавӣ дар минтақа зарур аст, то аз фазоҳои химиявӣ дар деворҳои дохилии шӯрӣ пешгирӣ шавад. Обҳои сахт метавонанд тавассути вақт боиси осипани калсий бар рӯи сӯроҳҳои шӯрӣ шаванд, ки боиси коҳиши раводорӣ мегардад.</p>\n<h2>Мушкилоти маъмул дар нигоҳдории шӯрӣ</h2>\n<p>Бо вуҷуди тамоми фоидаҳо, шӯрӣ низ бо мушкилоти зиёде дучор аст. Муҳимтарин ин мушкилӣ, пӯсиши сӯроҳҳои шӯрӣ аз сабаби осипан ё арзёнии сӯлоҳ мебошад. Ин мушкилӣ метавонад ба коҳиши якхелагии паҳн кардани об оварда расонад ва сифати калабасабзиро коҳиш диҳад. Яке аз роҳҳои ҳалли ин мушкилӣ, истифодаи филтрҳои мувофиқ дар ҷои вориди об аст. Филтрҳои турбо ва қалъагӣ бояд бо тартибот тоза карда шаванд. Агар манбаи обатон чӯб бошад, барои коҳиши сахтии об пеш аз ворид шудан ба шӯрӣ, лозимият ба дисафаксия доред. Дигар на, пӯсишҳои микробӣ метавонанд дар фаслҳои гарм, ки сӯлоҳҳо тез меафзоянд, ба зудӣ пеш рафта, шӯриро баста қарор диҳанд.</p>\n<p>Иловаз ғалғишӣ, тафтои физикии лентаи капиллярӣ низ як мушкилоти ҷиддӣ ҳисоб мешавад. Ин системаҳо одатан барои як сол тарҳрезӣ шудаанд ва муқовиматашон нисбат ба шӯхаҳои инфрасурхи офтоб маҳдуд аст. Агар лентаи капиллярӣ бевосита дар офтоб монда бошад, умри он ба таври ҷиддӣ кам мешавад. Барои ошноӣ бо хароҷотҳои муталлиқ ба лентаи капиллярӣ, сарфи ҳароҷоти ивазкунии лентаи капиллярӣ як омил муҳими иқтисодӣ аст. Яке аз истеҳсоли системаи обёрӣ бо капиляр дар муддати тӯлонӣ метавонад боиси сарфаи қобили диққати нӯшӯи об ва партовҳо гардад. Инчунин, ҳайвоноти вазҳ ё коҳуҳои деҳқонӣ метавонанд линтаҳоро задан ё хӯрдан, бинобар ин ҳифзи физикӣ аз линтаҳо бо чӯб ё торҳои сабук дар кӯчаҳои деҳқонӣ тавсия дода мешавад.</p>\n\n<h2>Нуқтаҳои асосии амалӣ барои ҳосилнокии баландтарин</h2>\n<p>Дар ин қисмат, ба нуқтаҳои амалӣ, ки аз ҷониби мутахассисони обёрӣ тавсия дода шудаанд, нигармем, то шумо тавонед беҳтарин натиҷаро аз картошкаҳо пайдо кунед. Риаи ин нуқтаҳо, сармоягузорӣ дар умри муфоди система ва сифати маҳсулот аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-کاهو-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری کاهو با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care калав</figcaption></figure>\n\n<ol>\n<li><strong>Омодагӣ ба хок пеш аз ниҳогӣ:</strong> Ҳолатро аз вуҷуди тошҳои калон дар минтақаи ниҳогии калав таъмин кунед, то решаҳо бо кушодашавии лентаи капиллярӣ мушкилӣ напайданд.</li>\n<li><strong>Моҳибии ҳарорати хок:</strong> Лентаи капилляриро дар чуқурии мувофиқ ҷойгир кунед, то аз тағйирёбии ҳарорат пешгирӣ кунед. Калав ҳарорати баландтар аз 25 дараҷаро дӯст надорад.</li>\n<li><strong>Шустаи мунтазами фалтерҳо:</strong> Ҳар ҳафта як бор фалтерҳои воридкунандагонро тафтиш ва тоза кунед, то кӯпакҳои намуна банд нашавад.</li>\n<li><strong>Маҳдуд кардани рӯшноии мустақим:</strong> Агар имкон бошад, аз сатҳҳои муносиб ё пӯшиши сабз истифода баред, то намунаи рӯшноӣ дар таҳти рӯшноии мустақими офтоб намонанд.</li>\n</ol>\n<h3>Идоракунии партоварӣ дар ҳамроҳӣ бо намунаи рӯшноӣ</h3>\n<p>Яке аз арзишҳои асосии намунаи рӯшноӣ, имконияти <strong>фитодорию</strong> (партоварӣ бо об) аст. Барои салат, истифодаи қотимҳои ҳалкунанда тавассути намунаи рӯшноӣ метавонад ҷабди бештари моддаҳои қувватбахшро осон кунад. Аз ҷиҳати <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D9%85%D8%A7%D8%B4-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Ҳаҷми бобар дар ҳектар</a> Барои салат, одатан зичии мувофиқ байни 10000 то 15000 ниҳол дар ҳектар аст. Дар ин зичӣ, пастаи қалғасакӣ метавонад хосиши оби лозимахоро хуб таъмин кунад. Инчунин, истифодаи фосфатҳо барои танзими кислотагии об метавонад аз афзоиш ё афканӣ дар пастаи қалғасакӣ пешгирӣ кунад. Кунадихӣ тавассути пастаи қалғасакӣ бояд дар соатҳои хунки рӯз ва бо ҷараёни давомноки об иҷро шавад, то ки консентратсияи баланди моддаҳои ғизоӣ боиси сӯзонидани решаҳои нозуки салат нашавад. Мувозинат байни моддаҳои ғизоӣ, монанди потассий ва кальций дар барномаи кунадихӣ, сифати нигоҳдории сари салат пас аз ҷамъовариро низ муайян мекунад.</p>\n<h2>Ҷавоб ба саволҳои маъмул дар бораи пастаи қалғасакӣ</h2>\n<p>Дар ин қисм, ба муҳимтарин саволҳое, ки деҳқонон дар бораи нигоҳдории салат бо пастаи қалғасакӣ доранд, ҷавоб медиҳем. Ин ҷавобҳо бар асоси таҷрибаҳои майдонӣ тартиб дода шудаанд.</p>\n<p><strong>Савол 1: Оё метавон аз пастаи қалғасакӣ чанд сол истифода бурд?</strong><br>Тавсия мешавад, ки аз пастаҳои қалғасаки яксола истифода баред ва дар фавсӯи оянда онҳоро иваз кунед. Ҳарчанд пастаҳои чандсола (бо пошониши муқовиматбахш ба UV) ду то се сол устода меоянд, вале самаранокии онҳо кам мешавад. Дар пастаҳои қадимӣ ғафсии деворҳо кам мешавад ва барориши баробарӣ гум мешавад, ки барои салат мувофиқ нест.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-کاهو-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری کاهو با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>crop drip tape maintenance care салат</figcaption></figure>\n\n<p><strong>Савол 2: Беҳтарин замон барои насби пастаи қалғасаки салат кист?</strong><br>Пеш аз наботи қаҳу, лентаро дар амики 5 то 10 сантиметр аз хок насб кунед. Агар лента дар сатҳ боқӣ монад, дар натиҷаи ҷойи хок хаш меояд. Насби барвақт боиси он мегард, ки обёрии ибтидоии зироат решагуниши тезтарро ба вуҷуд меорад.</p>\n<p><strong>Саволи 3: Чӣ тавр муайян кунам, ки лента пӯшида шудааст?</strong><br>Камшавии баробарнамоии хориши об аз лентаро гуногун, мавҷуд будани лохушҳои хушк бар хок, ё мушоҳидаи алағуғуррӣ дар ғаллакунандаҳо аломатҳои пӯшидан мебошанд. Дар ин ҳолат, шустани баръакс бо фишори баланд ё иваз кардани филтр лозим аст. Инчунин, назорати деҳии баромади лентаро дар оғоз ва охири хат, усули суръаттарин барои муайян кардани камшавии фишор мебошад.</p>\n\n<h2>Хулосабардорӣ ва тасдиқи роҳҳои ивазкунанда</h2>\n<p>Истифодаи лентаро барои қаҳу як сармоягузории ҳокимона барои зиёд кардани ҳосилнокӣ ва кам кардани истифодаи об мебошад. Бо риоя кардани нуқтаҳои амалӣ, аз ҷумла интихоби диаметри мувофиқ, назорати филтрҳо ва истифодаи пойгонкашҳи UV, метавон беҳтарин натиҷаро дар зироат даст овард. Ба ғайр аз қаҳу, системаҳои лентавӣ ҳамчунин барои сабзавоти монанд ба қитоб ва кинава истифода меёбанд. Барои омӯзиши бештар дар бораи <a href="https://navar-abyari.ir/melon-seed-quantity-per-hectare-planting-density-table/">миқдори тоъри қитоб ва ҷойгиркунии гектар</a> ё <a href="https://navar-abyari.ir/quinoa-tuhmi-dar-ghektar/">зироати кинава дар гектар</a>Шум метавонед ба манбади ихтисосии алоқаманд муроҷиат кунед. Дар охир, нигоҳдории дурусти системаи наварҳои ройлерӣ (нӯрӣ) калиди расидан ба маҳсулоти сабзии хоси (каҳу) саломат ва аз атрак пуррост. Ин роҳуравшавиҳо на танҳо фоирангезиро меафзунанд, балки устувории муҳити зисти кишовариро низ бо кам кардани истиноди обҳои ширин боло мебаранд.</p>','Фармоиши салат бо лентаи пӯлод: Нуқтаҳои калидӣ барои ҳосилнокӣи баланд','Салат яке аз баргиҳҳои ҳассос ба намӣ мебошад. Дар ин дастур мо усулҳои нигоҳубинии шитоби салат ва омилҳое, ки ба самаранокии ин системаи обёрӣ таъсир мерасонанд,ро баррасӣ мекунем.','publish','closed','closed','farmoish-salat-lenta-steel',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
