INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','آشنایی با هزینه‌های کشت شنبلیله با روش نوار تیپ به ازای هر هکتار. راهنمای کامل و کاربردی برای کشاورزان با جزئیات فنی دقیق.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
