INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تحليل دقيق لتكلفة زراعة الجذور في الأفق باستخدام نظام الري بالتنقيط في الهكتار. معلومات شاملة للمزارعين العراق حول الجدوى الاقتصادية والتطبيق الفني الفعلي.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
